1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface Damage {
13	  itemType: string;
14	  amount: number;
15	}
16	
17	export interface Incident {
18	  cause: string;
19	  damages: Damage[];
20	}
21	
22	export type Step =
23	  | { op: "quote"; items: Item[] }
24	  | { op: "claim"; policy: number; incident: Incident };
25	
26	export interface Scenario {
27	  customer: Customer;
28	  steps: Step[];
29	}
30	
31	export type StepResult =
32	  | { premium: number }
33	  | { payout: number; remainingCap: number };
34	
35	export interface ScenarioResult {
36	  results: StepResult[];
37	}
38	
39	const PROCESSING_FEE = 5;
40	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
41	
42	const percentOf = (amount: number, percent: number): number =>
43	  (amount * percent) / 100;
44	
45	const BASE_PREMIUM_BY_ITEM_TYPE = {
46	  sword: 100,
47	  amulet: 60,
48	  staff: 80,
49	  potion: 40,
50	  rune: 25,
51	} as const satisfies Record<string, number>;
52	
53	type InsurableItemType = keyof typeof BASE_PREMIUM_BY_ITEM_TYPE;
54	
55	const basePremiumOf = (item: Item): number =>
56	  BASE_PREMIUM_BY_ITEM_TYPE[item.type as InsurableItemType];
57	
58	const sumBasePremiums = (items: Item[]): number =>
59	  items.reduce((sum, item) => sum + basePremiumOf(item), 0);
60	
61	const quotePremium = (items: Item[]): number => {
62	  const base = sumBasePremiums(items);
63	  const withSurcharge =
64	    base + percentOf(base, FIRST_INSURANCE_SURCHARGE_PERCENT);
65	  return Math.ceil(withSurcharge + PROCESSING_FEE);
66	};
67	
68	const runStep = (step: Step): StepResult => {
69	  if (step.op === "quote") return { premium: quotePremium(step.items) };
70	  throw new Error("claim steps are not implemented yet");
71	};
72	
73	export const runScenario = (scenario: Scenario): ScenarioResult => ({
74	  results: scenario.steps.map(runStep),
75	});
